static mblk_t * ipw2200_m_tx ( void * arg , mblk_t * mp ) { struct ipw2200_softc * sc = ( ipw2200_softc * ) arg ; struct ieee80211com * ic = & sc -> sc_ic ; mblk_t * next ; if ( sc -> sc_flags & IPW2200_FLAG_SUSPEND ) { IPW2200_DBG ( IPW2200_DBG_SUSPEND , ( sc -> sc_dip , CE_CONT , "ipw2200_m_tx(): suspend status, discard msg\n" ) ) ; sc -> sc_stats . sc_tx_discard ++ ; freemsgchain ( mp ) ; return ( NULL ) ; } if ( ic -> ic_state != IEEE80211_S_RUN ) { IPW2200_DBG ( IPW2200_DBG_GLD , ( sc -> sc_dip , CE_CONT , "ipw2200_m_tx(): discard msg, ic_state = %u\n" , ic -> ic_state ) ) ; sc -> sc_stats . sc_tx_discard ++ ; freemsgchain ( mp ) ; return ( NULL ) ; } while ( mp != NULL ) { next = mp -> b_next ; mp -> b_next = NULL ; if ( ipw2200_send ( ic , mp , IEEE80211_FC0_TYPE_DATA ) == ENOMEM ) { break ; } mp = next ; } return ( mp ) ; } 